const TS={family:'Tenor Sans',style:'Regular'};
function T(chars,size,color,opts={}){const t=figma.createText();t.fontName=TS;t.characters=chars;t.fontSize=size;t.fills=[{type:'SOLID',color:rgb(color)}];if(opts.ls!==undefined)t.letterSpacing={type:'PIXELS',value:opts.ls};if(opts.lh)t.lineHeight={type:'PIXELS',value:opts.lh};if(opts.align)t.textAlignHorizontal=opts.align;if(opts.name)t.name=opts.name;return t;}
function F(name,opts={}){const f=figma.createFrame();f.name=name;if(opts.fill)f.fills=[{type:'SOLID',color:rgb(opts.fill)}];else f.fills=[];if(opts.auto){f.layoutMode=opts.dir||'VERTICAL';f.itemSpacing=opts.gap||0;if(opts.pad!==undefined){f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=opts.pad;}if(opts.padX!==undefined){f.paddingLeft=f.paddingRight=opts.padX;}if(opts.padY!==undefined){f.paddingTop=f.paddingBottom=opts.padY;}f.counterAxisAlignItems=opts.ca||'MIN';f.primaryAxisAlignItems=opts.pa||'MIN';}if(opts.w)f.resize(opts.w,opts.h||10);if(opts.clip!==undefined)f.clipsContent=opts.clip;return f;}
