function T(str,size,color,opts){opts=opts||{};const t=figma.createText();t.fontName={family:'Tenor Sans',style:'Regular'};t.characters=str;t.fontSize=size;t.fills=[{type:'SOLID',color:color||INK}];if(opts.ls!==undefined)t.letterSpacing={value:opts.ls,unit:'PIXELS'};if(opts.lh)t.lineHeight={value:opts.lh,unit:'PIXELS'};if(opts.w){t.textAutoResize='HEIGHT';t.resize(opts.w,t.height);}if(opts.align)t.textAlignHorizontal=opts.align;if(opts.name)t.name=opts.name;return t;}
function B(str,size,color,opts){opts=opts||{};const t=figma.createText();t.fontName={family:'Bodoni Moda',style:opts.style||'Bold Italic'};t.characters=str;t.fontSize=size;t.fills=[{type:'SOLID',color:color||INK}];if(opts.w){t.textAutoResize='HEIGHT';t.resize(opts.w,t.height);}if(opts.align)t.textAlignHorizontal=opts.align;if(opts.lh)t.lineHeight={value:opts.lh,unit:'PIXELS'};return t;}
function F(w,h,color,radius){const f=figma.createFrame();f.resize(w,h);f.fills=[{type:'SOLID',color:color||WHITE}];f.clipsContent=true;if(radius!==undefined)f.cornerRadius=radius||0;return f;}
function inst(name,parent,x,y,w,h){const comp=C[name];if(!comp)throw new Error('missing comp '+name);const i=comp.createInstance();if(parent)parent.appendChild(i);if(x!==undefined){i.x=x;i.y=y;}if(w!==undefined)i.resize(w,h);return i;}
function img(name,parent,x,y,w,h){const i=inst(name,parent,x,y,w,h);const f=i.fills&&i.fills.length?i.fills[0]:null;if(f&&f.type==='IMAGE'){const nf=JSON.parse(JSON.stringify(f));nf.scaleMode='FILL';i.fills=[nf];}else{const inner=i.findOne(n=>n.fills&&n.fills.length&&n.fills[0].type==='IMAGE');if(inner){const nf=JSON.parse(JSON.stringify(inner.fills[0]));nf.scaleMode='FILL';inner.fills=[nf];}}return i;}
function shell(frame,dark){const sb=inst('Status Bar',frame,0,0);if(dark){for(const v of sb.findAll(n=>n.type==='VECTOR'))v.fills=[{type:'SOLID',color:WHITE}];for(const v of sb.findAll(n=>n.type==='TEXT'))v.fills=[{type:'SOLID',color:WHITE}];}const hi=inst('Home Indicator',frame,0,frame.height-34);if(dark){for(const v of hi.findAll(n=>n.type==='VECTOR'||n.type==='RECTANGLE'))v.fills=[{type:'SOLID',color:WHITE}];}}
function dots(parent,n,active,color){const row=figma.createFrame();row.layoutMode='HORIZONTAL';row.itemSpacing=6;row.counterAxisAlignItems='CENTER';row.fills=[];parent.appendChild(row);for(let i=0;i<n;i++){const d=figma.createEllipse();d.resize(i===active?8:6,i===active?8:6);d.fills=[{type:'SOLID',color:i===active?(color||TERRA):LINE}];row.appendChild(d);}return row;}
function tabI(parent,label,active){const t=inst('Tab',parent);t.findOne(n=>n.name==='Label').characters=label;const d=t.findOne(n=>n.name==='Dot');d.visible=!!active;if(active)d.fills=[{type:'SOLID',color:TERRA}];return t;}
function cardI(parent,photo,brand,name,price){const c=inst('ProductCard',parent);const ph=c.findOne(n=>n.name==='Photo');if(C[photo]&&ph.swapComponent)ph.swapComponent(C[photo]);if(brand)c.findOne(n=>n.name==='Brand').characters=brand;c.findOne(n=>n.name==='Name').characters=name;c.findOne(n=>n.name==='Price').characters=price;return c;}

