function fixBanner(b, w){
  b.resize(w, 200);
  // fix children widths
  for (const c of b.children){
    if (c.name && c.name.startsWith && (c.type==='RECTANGLE'||c.type==='INSTANCE')) { if(c.width===343) c.resize(w, c.height===72?72:200); }
    if (c.type==='TEXT' && c.width===343){ c.resize(w, c.height); }
  }
  // reposition texts
  const nt = b.findOne(n=>n.type==='TEXT'&&n.characters==='02'||n.type==='TEXT'&&n.characters==='03');
}
fixBanner(b2,163); fixBanner(b3,163);
// reposition text inside each
for (const b of [b2,b3]){
  const texts = b.findAll(n=>n.type==='TEXT');
  for (const t of texts){
    if (t.width>163){ t.textAutoResize='HEIGHT'; t.resize(163,t.height); }
  }
  // image instance
  const im = b.findOne(n=>n.type==='INSTANCE');
  if (im && im.width===343) im.resize(163,200);
  const sc = b.findOne(n=>n.type==='RECTANGLE');
  if (sc && sc.width===343) sc.resize(163,72);
}
