const out=[];
function walk(n,frameName,path){
  if(n.reactions&&n.reactions.length){
    for(const r of n.reactions){
      const a=r.actions[0];
      if(a&&a.type==='NODE')out.push(frameName+' | '+path+' -> '+(idToName[a.destinationId]||a.destinationId));
    }
  }
  if('children' in n)for(const ch of n.children)walk(ch,frameName,path+'/'+ch.name);
}
