const log=[];

// 1. Dedupe duplicate reactions everywhere
function dedupe(n){
  if(n.reactions&&n.reactions.length>1){
    const seen=new Set();const keep=[];
    for(const r of n.reactions){
      const a=r.actions[0];
      const key=(a&&a.type==='NODE')?(a.destinationId):JSON.stringify(r);
      if(!seen.has(key)){seen.add(key);keep.push(r);}
    }
    if(keep.length!==n.reactions.length){n.reactions=keep;log.push('dedupe '+n.name);}
  }
  if('children' in n)for(const ch of n.children)dedupe(ch);
}
